<template>
  <section class="page">
    <header class="hero"><div><p class="eyebrow">STORY AGENT · STAGE 8 · READ-ONLY FINALIZATION PREFLIGHT</p><h2>Signed Release 终局预检</h2><p>复用 professional finalization v2 候选门禁，逐项目核对成品、真实修订增量、签名盲评、外部 trust 与 durable release。</p></div><RouterLink to="/story/stage8-blind-review-signature">返回盲评签名</RouterLink></header>
    <div class="truth"><strong>Candidate ≠ Signed Release ≠ Professional Pass</strong><span>本页只做内存 dry-run；不持久化输入、不启动 finalization、不签发 release。</span></div>
    <p v-if="errorMessage" class="error">{{ errorMessage }}</p>
    <template v-if="workspace && result">
      <section class="summary"><article><span>项目</span><b>75</b></article><article><span>Artifact Ready</span><b>{{ workspace.summary.artifact_completion_ready_project_count }}</b></article><article><span>Revision Δ Ready</span><b>{{ workspace.summary.verified_revision_delta_ready_project_count }}</b></article><article><span>Signed Review Ready</span><b>{{ workspace.summary.signed_blind_review_ready_project_count }}</b></article><article><span>Trust Ready</span><b>{{ workspace.summary.external_trust_ready_project_count }}</b></article><article><span>Candidate / Release / Pro</span><b class="zero">0 / 0 / 0</b></article></section>
      <section class="toolbar"><label>固定项目<select v-model="selectedBenchmarkId" @change="reload"><option v-for="project in workspace.projects" :key="project.benchmark_id" :value="project.benchmark_id">{{ project.video_type }} · {{ project.benchmark_id }}</option></select></label><button :disabled="validating" @click="validate">{{ validating ? '校验中' : '仅运行预检' }}</button></section>
      <section class="editors"><article><header><h3>Finalization Input v2</h3><button @click="copy(finalizationRaw)">复制</button></header><textarea v-model="finalizationRaw" aria-label="Stage 8 finalization input JSON" spellcheck="false" /></article><article><header><h3>External Trust Policy</h3><button @click="copy(trustRaw)">复制</button></header><textarea v-model="trustRaw" aria-label="Stage 8 finalization trust policy JSON" spellcheck="false" /></article></section>
      <section class="results"><article class="checks"><header><div><p class="eyebrow">FAIL-CLOSED GATES</p><h3>{{ result.checks.eligible_for_signed_release ? 'Candidate Ready（仍未发布）' : '终局材料未就绪' }}</h3></div><b>{{ passedChecks }}/{{ checkEntries.length }}</b></header><div><p v-for="[key,value] in checkEntries" :key="key"><i :class="value ? 'ok' : 'no'">{{ value ? '✓' : '×' }}</i>{{ label(key) }}</p></div></article><article class="blockers"><p class="eyebrow">PROJECT READINESS</p><h3>{{ selectedProject?.benchmark_id }}</h3><dl><div v-for="item in laneEntries" :key="item[0]"><dt>{{ laneLabel(item[0]) }}</dt><dd>{{ item[1] ? 'READY' : 'BLOCKED' }}</dd></div></dl><h4>Decision blockers · {{ result.decision.blockers.length }}</h4><ul><li v-for="code in result.decision.blockers.slice(0,12)" :key="code">{{ code }}</li></ul></article></section>
    </template>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { Stage8FinalizationPreflightResult, Stage8FinalizationPreflightWorkspace } from '@shared/types'
import { getStage8FinalizationPreflightWorkspace, validateStage8FinalizationPreflight } from '../api/stage8-blind-review'
const workspace=ref<Stage8FinalizationPreflightWorkspace|null>(null),result=ref<Stage8FinalizationPreflightResult|null>(null),selectedBenchmarkId=ref(''),finalizationRaw=ref(''),trustRaw=ref(''),errorMessage=ref(''),validating=ref(false)
const selectedProject=computed(()=>workspace.value?.projects.find(item=>item.benchmark_id===selectedBenchmarkId.value)),checkEntries=computed(()=>Object.entries(result.value?.checks??{})),passedChecks=computed(()=>checkEntries.value.filter(([,value])=>value).length),laneEntries=computed(()=>Object.entries(selectedProject.value?.checks??{}))
onMounted(()=>reload())
async function reload(){const response=await getStage8FinalizationPreflightWorkspace(selectedBenchmarkId.value);if(!response.ok||!response.data){errorMessage.value=response.error?.message??'终局预检加载失败';return}workspace.value=response.data;selectedBenchmarkId.value=response.data.selected_benchmark_id;finalizationRaw.value=response.data.finalization_input_template_raw_json;trustRaw.value=response.data.trust_policy_template_raw_json;result.value=response.data.template_preflight}
async function validate(){validating.value=true;errorMessage.value='';try{const response=await validateStage8FinalizationPreflight({expected_benchmark_id:selectedBenchmarkId.value,finalization_input_raw_json:finalizationRaw.value,trust_policy_raw_json:trustRaw.value});if(!response.ok||!response.data){errorMessage.value=response.error?.message??'终局预检失败';return}result.value=response.data}finally{validating.value=false}}
async function copy(value:string){try{await navigator.clipboard.writeText(value)}catch{errorMessage.value='浏览器未授权复制'}}
const labels:Record<string,string>={request_valid:'请求完整',finalization_input_json_valid:'Input JSON',trust_policy_json_valid:'Trust JSON',benchmark_binding_valid:'Benchmark绑定',video_type_binding_valid:'片型绑定',finalization_input_schema_valid:'Finalization v2 schema',external_trust_policy_valid:'外部trust',professional_artifact_completion_ready:'12件专业成品',verified_real_revision_delta_ready:'真实修订增量',signed_external_blind_review_ready:'三角色签名盲评',eligible_for_signed_release:'Candidate资格',durable_signed_release_present:'Durable signed release',source_claimed_credit_rejected:'拒绝自报信用'}
const lanes:Record<string,string>={professional_artifact_completion_ready:'专业成品',verified_real_revision_delta_ready:'真实修订增量',signed_external_blind_review_ready:'签名盲评',external_trust_policy_ready:'外部Trust',finalization_candidate_ready:'Candidate',durable_signed_release_present:'Signed Release'}
function label(key:string){return labels[key]??key} function laneLabel(key:string){return lanes[key]??key}
</script>

<style scoped>
