ea{width:100%;height:330px;padding:12px;box-sizing:border-box;resize:vertical;border:0;outline:0;color:#ebe4f0;background:#0d0a11;font:9px/1.5 ui-monospace,SFMono-Regular,monospace}.checks>div{padding:10px;display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.checks p{margin:0;padding:8px;border-radius:6px;background:#30283b;font-size:8px}.checks i{margin-right:6px;font-style:normal}.ok{color:#8fe19e}.no{color:#ff9ba5}.blockers{padding:13px}.blockers dl{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.blockers dl div{padding:9px;border-radius:7px;background:#30283b}.blockers dt{color:#a99eb5;font-size:8px}.blockers dd{margin:4px 0 0;color:#ff9ba5;font-weight:800;font-size:9px}.blockers ul{max-height:145px;margin:0;padding-left:19px;overflow:auto;color:#d4c9dd;font:9px/1.6 ui-monospace,monospace}@media(max-width:1000px){.summary{grid-template-columns:repeat(3,1fr)}.editors,.results{grid-template-columns:1fr}.toolbar{align-items:flex-start;flex-direction:column}.toolbar select{min-width:0;width:100%}}@media(max-width:650px){.page{padding:18px 12px}.hero,.truth{align-items:flex-start;flex-direction:column}.summary,.checks>div,.blockers dl{grid-template-columns:1fr}}
</style>
